import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import jakarta.transaction.Transactional;

@Service
@Slf4j
@RequiredArgsConstructor
public class LocationService {
    
   private final LocationRepository locationRepository;
    
    @Transactional
    public Location registerALocation(String name){
    // Activity: registerALocation      
    // InitialNode: Init
    // Declaration: Declare new location 
    Location newLocation = new Location();
    // Assignment: newLocation.name = name
    newLocation.setName(name);
    
    // CallOperationAction: Persist Location 
     newLocation = locationRepository.save(newLocation);
    
    return newLocation;
   }

    @Transactional
    public Boolean existsByPortCode(Integer portCode){
    // Activity: existsByPortCodeDomainService      
    // InitialNode: existsByPortCodeDomainService-InitNode
    // CallOperationAction: existsByPortCode 
    Boolean result = locationRepository.existsByPortCode(portCode);
    
    return result;
   };
 
}
